<script setup>
import { ref, onMounted } from 'vue'
import { Plus, Users, ArrowUpRight, Trash2, Wallet, X, UserPlus, Sparkles } from 'lucide-vue-next'
import { get, post, del, money } from '../services/api'
const groups=ref([]), loading=ref(true), error=ref(''), show=ref(false), busy=ref(false)
const name=ref(''), description=ref(''), budget=ref(''), members=ref('')
async function load(){loading.value=true;try{groups.value=await get('/groups');error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
async function create(){error.value='';if(!name.value.trim()){error.value='Give your group a name.';return}busy.value=true;try{await post('/groups',{name:name.value,description:description.value,budget:budget.value?Number(budget.value):null,members:members.value.split(',').map(s=>s.trim()).filter(Boolean)});show.value=false;name.value='';description.value='';budget.value='';members.value='';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function remove(g){if(!confirm(`Delete "${g.name}" and its expenses? This cannot be undone.`))return;try{await del(`/groups/${g.id}`);await load()}catch(e){error.value=e.message}}
async function seed(){try{await post('/demo/seed',{});await load()}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template>
  <div class="page-stack">
    <section class="page-intro"><div><div class="eyebrow">YOUR SHARED SPACES</div><h2>Better together.</h2><p>Create a group for trips, roommates, dinners, or anything you share.</p></div><div class="intro-actions"><button class="btn btn-secondary" @click="seed"><Sparkles :size="16"/> Load demo</button><button class="btn btn-primary" @click="show=true"><Plus :size="17"/> Create group</button></div></section>
    <p v-if="error" class="alert alert-error">{{ error }}</p>
    <div v-if="loading" class="loading-grid"><div v-for="n in 3" :key="n" class="skeleton-card"></div></div>
    <div v-else-if="!groups.length" class="panel empty-state large-empty"><div class="empty-icon"><Users :size="26"/></div><h3>Your first group starts here.</h3><p>Bring your people together and let SplitFlow handle the maths.</p><button class="btn btn-primary" @click="show=true"><Plus :size="16"/> Create your first group</button></div>
    <div v-else class="groups-grid"><article v-for="(g,i) in groups" :key="g.id" class="group-card"><div class="group-card-head"><div class="group-avatar big" :class="'avatar-'+(i%4)">{{ g.name.slice(0,1).toUpperCase() }}</div><button class="icon-btn danger-hover" @click="remove(g)" title="Delete group"><Trash2 :size="17"/></button></div><div class="group-card-title"><h3>{{ g.name }}</h3><p>{{ g.description || 'A shared space for expenses.' }}</p></div><div class="group-card-stats"><div><span>Total spent</span><strong>{{ money(g.total_expenses) }}</strong></div><div><span>Members</span><strong>{{ g.members.length }}</strong></div><div><span>Expenses</span><strong>{{ g.expense_count }}</strong></div></div><div v-if="g.budget" class="budget-line"><div class="budget-label"><span>Budget usage</span><strong>{{ Math.min(100,Math.round(g.total_expenses/g.budget*100)) }}%</strong></div><div class="progress-track"><span :class="{ warning:g.total_expenses/g.budget>=.75 }" :style="{width:Math.min(100,g.total_expenses/g.budget*100)+'%'}"></span></div></div><div class="member-stack"><div class="avatar-stack"><span v-for="(m,j) in g.members.slice(0,5)" :key="m.id" :title="m.name" :class="'stack-'+(j%4)">{{ m.name.slice(0,1).toUpperCase() }}</span></div><span>{{ g.members.map(m=>m.name).join(', ') || 'No members yet' }}</span></div><div class="group-card-actions"><RouterLink to="/expenses" class="btn btn-secondary btn-small">View expenses <ArrowUpRight :size="14"/></RouterLink><RouterLink to="/balances" class="btn btn-primary btn-small">Settle up</RouterLink></div></article></div>
    <div v-if="show" class="modal-backdrop" @click.self="show=false"><section class="modal"><div class="modal-head"><div class="modal-title-icon"><Users :size="20"/></div><div><h2>Create a group</h2><p>Set up a space for shared expenses.</p></div><button class="icon-btn" @click="show=false"><X :size="19"/></button></div><form class="modal-body" @submit.prevent="create"><label>Group name<input v-model="name" required placeholder="e.g. Goa trip, Flat 3B"/></label><label>Description<input v-model="description" placeholder="What's this group for?"/></label><label>Budget (₹, optional)<input v-model="budget" type="number" min="1" step=".01" placeholder="Set a spending limit"/></label><label>Members <span class="muted-inline">(comma-separated)</span><textarea v-model="members" rows="3" placeholder="Aarav, Diya, Kabir, Meera"></textarea><small class="field-help">You can add more members later. Duplicate names are removed.</small></label><div class="modal-actions"><button type="button" class="btn btn-secondary" @click="show=false">Cancel</button><button class="btn btn-primary" :disabled="busy">{{ busy?'Creating…':'Create group' }}</button></div></form></section></div>
  </div>
</template>
